from pathlib import Path
import json,shutil,zipfile,html,hashlib
r=Path(__file__).resolve().parents[1];cfg=json.loads((r/'campaign.json').read_text());caps=json.loads((r/'public/captions.json').read_text());report=json.loads((r/'verification.json').read_text());assert len(report)==4 and all(v['status']=='passed' for v in report)
dest=r.parent/'GRIFFE_BELA_STORIES_PRONTOS';dest.mkdir(exist_ok=True);release=r.parent/'entregas'/'griffe-bela-stories';release.mkdir(parents=True,exist_ok=True)
def ts(t):
 m=round(t*1000);return f'{m//3600000:02d}:{m//60000%60:02d}:{m//1000%60:02d},{m%1000:03d}'
index=['# Griffe Bela — quatro Stories para anúncios','', 'Quatro criativos com as fotos fornecidas e os dois áudios originais. Formato 1080 × 1920, 30 fps, H.264 + AAC. Marca com grafia confirmada pelo usuário.','', '| Vídeo | Duração | Direção | Narração |','| --- | --- | --- | --- |']
cards=[]
for v in cfg['videos']:
 folder=dest/v['slug'];folder.mkdir(exist_ok=True);src=r/'out'/v['slug'];shutil.copy2(src/'story.mp4',folder/'story.mp4');shutil.copy2(src/'capa.jpg',folder/'capa.jpg');shutil.copy2(src/'story.mp4',release/f'griffe-bela-story-0{v["id"]}.mp4')
 srt=[]
 for i,c in enumerate(caps[str(v['audio'])],1):srt.append(f"{i}\n{ts(c['start'])} --> {ts(c['end'])}\n{' '.join(w['text'] for w in c['words'])}\n")
 (folder/'legendas.srt').write_text('\n'.join(srt),encoding='utf-8');(folder/'anuncio.txt').write_text(f"TEXTO PRINCIPAL\n{v['post']}\n\nTÍTULO\n{v['title']}\n\nCTA VISUAL\nPeça o catálogo • Saiba mais\n\nDESTINO\nContato não informado. Configure o botão real do anúncio para o canal escolhido pela marca.\n",encoding='utf-8')
 index.append(f"| [{v['id']:02d} — {v['title']}]({v['slug']}/story.mp4) | {v['duration']:.2f}s | {'Vinho e dourado' if v['theme']=='wine' else 'Champanhe e creme'} | Áudio {'1' if v['audio']==34 else '2'} original |")
 esc=html.escape;slug=v['slug'];cards.append(f'<article><h2>{v["id"]:02d} · {esc(v["title"])}</h2><video controls playsinline preload="none" poster="{slug}/capa.jpg" src="{slug}/story.mp4"></video><p>{v["duration"]:.1f}s · Voz original</p><nav><a download href="{slug}/story.mp4">MP4</a><a download href="{slug}/capa.jpg">Capa</a><a download href="{slug}/legendas.srt">SRT</a><a download href="{slug}/anuncio.txt">Texto</a></nav></article>')
index+=['','## Uso','', 'Público: lojistas. Encerramento: Peça o catálogo / Saiba mais. O contato e o destino do botão não foram informados; configure o canal real no gerenciador de anúncios antes de veicular. Não há preços, descontos, escassez ou condições comerciais inventadas.','', 'As versões 01 e 03 usam o primeiro áudio com imagens e aberturas diferentes; 02 e 04 usam o segundo. Essa estrutura permite testar a direção visual conservando a mesma mensagem.','', 'A voz foi preservada, com ajuste de volume e remoção apenas de pequenas margens sem fala. Não houve mudança de velocidade nem narração sintética. As legendas têm correções de grafia, pontuação e nome da marca. Os modelos, rostos, roupas e cores das peças não foram recriados.','', 'Cada pasta contém story.mp4, capa.jpg, legendas.srt e anuncio.txt. Extraia o ZIP e abra index.html para assistir. Nenhum anúncio foi publicado automaticamente.']
(dest/'INDICE.md').write_text('\n'.join(index)+'\n',encoding='utf-8');shutil.copy2(r/'verification.json',dest/'verificacao.json')
page='''<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Griffe Bela · Stories</title><style>*{box-sizing:border-box}body{margin:0;background:#f4eee4;color:#431323;font:16px system-ui,sans-serif}header{background:#310c17;color:#fff6e9;padding:36px max(24px,calc((100vw - 1180px)/2))}h1{font-family:Georgia,serif;font-weight:400;font-size:40px;margin:0 0 12px}header p{line-height:1.6;max-width:850px;margin:0}main{max-width:1228px;margin:auto;padding:30px 24px;display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:22px}article{background:#fffaf3;padding:16px;border:1px solid #d9c7ae;border-radius:12px}h2{font-size:19px;line-height:1.4;min-height:55px;margin:0 0 14px}video{width:100%;aspect-ratio:9/16;display:block;background:#310c17;border-radius:5px}nav{display:flex;flex-wrap:wrap;gap:8px}a{padding:10px 12px;background:#431323;color:#fff6e9;border-radius:5px;text-decoration:none;font-size:14px}article p{font-size:14px}</style><header><h1>Griffe Bela · Coleção festa</h1><p>Quatro criativos para Stories, com fotos e narrações originais. Assista às versões e baixe os arquivos. Configure o contato real no botão do anúncio antes de veicular.</p></header><main>'''+''.join(cards)+'''</main><script>document.querySelectorAll('video').forEach(v=>v.addEventListener('play',()=>document.querySelectorAll('video').forEach(o=>{if(o!==v)o.pause()})))</script></html>'''
(dest/'index.html').write_text(page,encoding='utf-8');manifest={str(p.relative_to(dest)):{'bytes':p.stat().st_size,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()} for p in sorted(dest.rglob('*')) if p.is_file()};(dest/'ARQUIVOS.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2))
z=release/'GRIFFE_BELA_4_STORIES.zip'
with zipfile.ZipFile(z,'w',zipfile.ZIP_DEFLATED) as out:
 for p in sorted(dest.rglob('*')):
  if p.is_file():out.write(p,Path(dest.name)/p.relative_to(dest))
with zipfile.ZipFile(z) as out:assert out.testzip() is None
print('DELIVERY',z,z.stat().st_size,flush=True)
